#include <stdio.h>

struct point {
    double x;
    double y;
};

int main(void)
{
    struct point a = {1.5, 2.0};            /* in member order */
    struct point b = {.y = 4.0, .x = 3.0};  /* designated initialisers */
    struct point c = {.x = 9.0};            /* y becomes 0.0 */

    a.x = a.x + 1.0;                        /* member access with . */
    struct point d = a;                     /* copies both members */
    d.y = 100.0;                            /* does not affect a */

    printf("a = (%.1f, %.1f)\n", a.x, a.y);
    printf("b = (%.1f, %.1f)\n", b.x, b.y);
    printf("c = (%.1f, %.1f)\n", c.x, c.y);
    printf("d = (%.1f, %.1f)\n", d.x, d.y);
    printf("sizeof(struct point) = %zu\n", sizeof(struct point));
    return 0;
}

#include <stdio.h>

typedef struct {
    char name[32];
    double price;
    int stock;
} Product;

double stock_value(Product p)        /* receives a copy of the struct */
{
    return p.price * p.stock;
}

int main(void)
{
    Product pen = {"Ballpoint pen", 1.25, 40};
    printf("%s: %.2f each, %d in stock\n", pen.name, pen.price, pen.stock);
    printf("stock value: %.2f\n", stock_value(pen));
    return 0;
}

#include <stdio.h>

typedef struct {
    char name[32];
    double price;
    int stock;
} Product;

void restock(Product *p, int amount)
{
    p->stock += amount;                /* same as (*p).stock += amount */
}

void print_product(const Product *p)   /* read-only access, no copy */
{
    printf("%-14s %6.2f %4d\n", p->name, p->price, p->stock);
}

int main(void)
{
    Product pen = {"Ballpoint pen", 1.25, 40};
    print_product(&pen);
    restock(&pen, 60);
    print_product(&pen);
    return 0;
}

#include <stdio.h>

enum category { TOOL, FOOD, TOY };

typedef struct {
    const char *name;
    enum category kind;
    double price;
} Item;

const char *category_name(enum category c)
{
    switch (c) {
    case TOOL: return "tool";
    case FOOD: return "food";
    case TOY:  return "toy";
    }
    return "unknown";
}

int main(void)
{
    Item items[] = {
        {"hammer", TOOL, 12.5},
        {"apple", FOOD, 0.4},
        {"kite", TOY, 7.0},
        {"wrench", TOOL, 9.5},
    };
    size_t count = sizeof items / sizeof items[0];
    double tools = 0.0;

    for (size_t i = 0; i < count; i++) {
        printf("%-7s %-5s %5.2f\n", items[i].name,
               category_name(items[i].kind), items[i].price);
        if (items[i].kind == TOOL) tools += items[i].price;
    }
    printf("tools total: %.2f (TOOL = %d)\n", tools, TOOL);
    return 0;
}
